    "questionAr": "ليكن $X$ متغيراً عشوائياً متوسطه $\\mathbb{E}[X] = 2$ وتباينه $\\text{Var}(X) = 3$. إذا كان $Y = 2X + 5$، احسب التوقع $\\mathbb{E}[Y]$ والتباين $\\text{Var}(Y)$.",
