    "hintEn": "Eve's Law: Var(S) = E[N]*Var(X) + Var(N)*(E[X])^2 = lambda * (Var(X) + (E[X])^2) = lambda * E[X^2].",
    "hintAr": "قانون التباين الكلي: Var(S) = lambda * E[X^2] = lambda * (4 + 9) = 13 * lambda.",
    "stepByStepSolutionEn": [
      "1. Calculate $\\mathbb{E}[X^2] = \\text{Var}(X) + (\\mathbb{E}[X])^2 = 4 + 3^2 = 4 + 9 = 13$.",
      "2. Apply Eve's Law: $\\text{Var}(S) = \\mathbb{E}[\\text{Var}(S|N)] + \\text{Var}(\\mathbb{E}[S|N])$.",
      "3. $\\text{Var}(S) = \\mathbb{E}[N \\sigma^2] + \\text{Var}(N \\mu) = \\lambda \\sigma^2 + \\lambda \\mu^2 = \\lambda (\\sigma^2 + \\mu^2) = \\lambda \\mathbb{E}[X^2]$.",
      "4. Substitute $\\lambda = 4$: $\\text{Var}(S) = (4)(13) = 52$."
    ],
    "stepByStepSolutionAr": [
      "١. حساب العزم الثاني للمطالبة: $\\mathbb{E}[X^2] = 4 + 3^2 = 13$.",
      "٢. تطبيق قانون التباين الكلي: $\\text{Var}(S) = \\lambda \\sigma^2 + \\lambda \\mu^2 = \\lambda \\mathbb{E}[X^2]$.",
      "٣. بالتعويض: $\\text{Var}(S) = 4 \\times 13 = 52$.\""
    ],
    "teacherTipEn": "This fundamental actuarial formula explains why aggregate risk exceeds the sum of individual variances.",
    "teacherTipAr": "هذا القانون التأميني الأساسي يوضح سبب تجاوز المخاطر الإجمالية لمجرد جمع التباينات الفردية."
